/*
 * Extrae y loguea la información relevante del error.
 * Intenta recuperar identificadores de la línea afectada
 * (warmup_number_id, instance_name, phone_number) del contexto de error.
 */
const exec = $json.execution || {};
const wf   = $json.workflow  || {};
const err  = exec.error      || {};

// Fecha/hora legible en zona horaria Argentina
const nowArg = new Date(
  new Date().toLocaleString('en-US', { timeZone: 'America/Argentina/Buenos_Aires' })
);
const pad = n => String(n).padStart(2, '0');
const readableDate = `${pad(nowArg.getDate())}/${pad(nowArg.getMonth()+1)}/${nowArg.getFullYear()} ${pad(nowArg.getHours())}:${pad(nowArg.getMinutes())}:${pad(nowArg.getSeconds())} ARG`;

// Intentar extraer identificadores de la línea afectada del contexto serializado
const errStr       = JSON.stringify(err);
let warmupLineId   = null;
let instanceName   = null;
let phoneNumber    = null;

try {
  const lineMatch     = errStr.match(/"p_warmup_number_id"\s*:\s*"([0-9a-f\-]{36})"/);
  const instanceMatch = errStr.match(/"instance_name"\s*:\s*"([^"]+)"/);
  const phoneMatch    = errStr.match(/"p_phone_number"\s*:\s*"([^"]+)"|"phone_number"\s*:\s*"([^"]+)"/);

  if (lineMatch)     warmupLineId = lineMatch[1];
  if (instanceMatch) instanceName = instanceMatch[1];
  if (phoneMatch)    phoneNumber  = phoneMatch[1] || phoneMatch[2];
} catch (_) { /* campos opcionales — parsing no crítico */ }

const summary = {
  workflow_name:   wf.name               || 'desconocido',
  workflow_id:     wf.id                 || 'desconocido',
  execution_id:    exec.id               || 'desconocido',
  execution_url:   exec.url              || null,
  last_node:       exec.lastNodeExecuted || 'desconocido',
  error_message:   err.message           || 'Sin mensaje de error',
  warmup_line_id:  warmupLineId,
  instance_name:   instanceName,
  phone_number:    phoneNumber,
  occurred_at:     readableDate,
  occurred_at_iso: new Date().toISOString()
};

const lines = [
  `[WF-ERR-WARMUP] ============================================`,
  `  Workflow   : ${summary.workflow_name} (${summary.workflow_id})`,
  `  Execution  : ${summary.execution_id}`,
  `  Último nodo: ${summary.last_node}`,
  `  Error      : ${summary.error_message}`,
  summary.warmup_line_id ? `  Línea WU   : ${summary.warmup_line_id}` : null,
  summary.instance_name  ? `  Instancia  : ${summary.instance_name}`  : null,
  summary.phone_number   ? `  Teléfono   : ${summary.phone_number}`   : null,
  summary.execution_url  ? `  URL        : ${summary.execution_url}`  : null,
  `  Timestamp  : ${summary.occurred_at}`,
  `============================================================`
].filter(Boolean);

console.error(lines.join('\n'));

return [{ json: summary }];
